CREATE TABLE "employee_permissions" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "employee_permissions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"employee_id" text NOT NULL,
	"permission" text NOT NULL,
	"valid_from" timestamp with time zone DEFAULT now() NOT NULL,
	"valid_to" timestamp with time zone
);
--> statement-breakpoint
ALTER TABLE "employee_permissions" ADD CONSTRAINT "employee_permissions_employee_id_empleado_id_fk" FOREIGN KEY ("employee_id") REFERENCES "public"."empleado"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "employee_permissions_employee_idx" ON "employee_permissions" USING btree ("employee_id");--> statement-breakpoint
CREATE UNIQUE INDEX "employee_permissions_vigente_uq" ON "employee_permissions" USING btree ("employee_id","permission") WHERE "employee_permissions"."valid_to" IS NULL;--> statement-breakpoint
-- H-032: quien hoy trabaja leads (rol vigente Doer, Manager, Coordinator o Admin) conserva lo que podía hacer.
INSERT INTO "employee_permissions" ("employee_id", "permission")
SELECT DISTINCT a."empleado_id", p.permiso
FROM "asignacion" a
JOIN "empleado" e ON e."id" = a."empleado_id" AND e."valid_to" IS NULL
CROSS JOIN (VALUES ('leads.importar'), ('leads.ver'), ('leads.editar'), ('leads.convertir')) AS p(permiso)
WHERE a."valid_to" IS NULL AND a."rol_id" IN ('doer', 'manager', 'coordinator', 'configurador-admin');
